refentry.refsect1:
  &reftitle.examples;

   Exemple avec Yaf_Route_Rewrite


<?php
   /**
    * Ajoute une route de réécriture à la pile de routes de Yaf_Router
    */
    Yaf_Dispatcher::getInstance()->getRouter()->addRoute("name",
        new Yaf_Route_Rewrite(
           "/product/:name/:id/*", //correspond aux URI de requête commençant par "/product"
           array(
               'controller' => "product",  //route vers le contrôleur product,
           ),
        )
    );
?>


   &example.outputs.similar;


/* pour http://yourdomain.com/product/foo/22/foo/bar
 * la route donnera les valeurs suivantes :
 */
array(
  "controller" => "product",
  "module"     => "index", //(par défaut)
  "action"     => "index", //(par défaut)
)

/**
 * et les paramètres de requête :
 */
array(
  "name" => "foo",
  "id"   => 22,
  "foo"  => bar
)




   Exemple avec Yaf_Route_Rewrite


    <?php
   /**
    * Ajoute une route de réécriture à la pile de routes de Yaf_Router en appelant addconfig
    */
    $config = array(
        "name" => array(
           "type"  => "rewrite",        //route Yaf_Route_Rewrite
           "match" => "/user-list/:id", //correspond uniquement à /user/list/?/
           "route" => array(
               'controller' => "user",  //route vers le contrôleur user,
               'action'     => "list",  //route vers l'action list
           ),
        ),
    );
    Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
        new Yaf_Config_Simple($config));
?>


   &example.outputs.similar;


/* pour http://yourdomain.com/user-list/22
 * la route donnera les valeurs suivantes :
 */
array(
  "controller" => "user",
  "action"     => "list",
  "module"     => "index", //(par défaut)
)

/**
 * et les paramètres de requête :
 */
array(
  "id"   => 22,
)




   Exemple avec Yaf_Route_Rewrite (à partir de 2.3.0)


    <?php
   /**
    * Ajoute une route de réécriture utilisant le résultat de la correspondance comme nom m/c/a
    */
    $config = array(
        "name" => array(
           "type"  => "rewrite",
           "match" => "/user-list/:a/:id", //correspond uniquement à /user-list/*
           "route" => array(
               'controller' => "user",   //route vers le contrôleur user,
               'action'     => ":a",     //route vers l'action :a
           ),
        ),
    );
    Yaf_Dispatcher::getInstance()->getRouter()->addConfig(
        new Yaf_Config_Simple($config));
?>


   &example.outputs.similar;


/* pour http://yourdomain.com/user-list/list/22
 * la route donnera les valeurs suivantes :
 */
array(
  "controller" => "user",
  "action"     => "list",
  "module"     => "index", //(par défaut)
)

/**
 * et les paramètres de requête :
 */
array(
  "id"   => 22,
)
